import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader input = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        int T = 1;
        while (T-- > 0) {
            String s = input.next();
            if (s.length() == 1) {
                out.println(isSpecialChar(s.charAt(0)) ? 1 : 0);
            } else {
                if (s.indexOf('X') == -1) {
                    out.println(calculateWays(s));
                } else {
                    int sum = 0;
                    for (int digit = 0; digit < 10; digit++) {
                        sum += calculateWays(substituteX(s, (char) ('0' + digit)));
                    }
                    out.println(sum);
                }
            }
        }
        out.close();
    }

    private static boolean isSpecialChar(char c) {
        return c == '0' || c == '_' || c == 'X';
    }

    private static String substituteX(String s, char replacement) {
        return s.replace("X", String.valueOf(replacement));
    }

    public static int calculateWays(String s) {
        int n = s.length();
        int prefix = (s.charAt(0) == '0') ? 0 : 1;
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                prefix *= (i == 0) ? 9 : 10;
            }
        }
        int suffix = 0;
        if (n >= 2) {
            char c1 = s.charAt(n - 2);
            char c2 = s.charAt(n - 1);
            if (c1 == '_' && c2 == '_') {
                suffix = (n == 2) ? 3 : 4;
            } else if (c2 == '_') {
                if (c1 == '0' || c1 == '5' || c1 == '2' || c1 == '7') {
                    suffix = 1;
                }
            } else if (c1 == '_') {
                if (c2 == '0') {
                    suffix = (n == 2) ? 1 : 2;
                } else if (c2 == '5') {
                    suffix = 2;
                }
            } else {
                int val = Integer.parseInt(s.substring(n - 2));
                suffix = (val % 25 == 0) ? 1 : 0;
            }
        }
        return prefix * suffix;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}
